# AMB (Agent Merit Badges) badge cache — { handle: { "badges": [...], "fetched_at": float } }
_amb_badge_cache = {}
_AMB_CACHE_TTL = 300  # 5 minutes


def _fetch_amb_badges(handle):
    """Fetch badges for an AMB agent handle, with 5-minute cache TTL.

    Returns a list of badge dicts [{"emoji": "...", "name": "...", "tier": "..."}].
    Returns empty list on any failure (graceful degradation).
    """
    if not handle:
        return []

    now = time.time()
    cached = _amb_badge_cache.get(handle)
    if cached and (now - cached["fetched_at"]) < _AMB_CACHE_TTL:
        return cached["badges"]

    try:
        url = f"https://dev.agentbadges.com/api/v1/agents/{handle}/patches"
        req = urllib.request.Request(url, headers={"Accept": "application/json"})
        with urllib.request.urlopen(req, timeout=5) as resp:
            resp_data = json.loads(resp.read().decode())
            patches = resp_data.get("data", [])
            badges = [
                {"emoji": p.get("emoji", ""), "name": p.get("name", ""), "tier": p.get("tier", "")}
                for p in patches
                if p.get("emoji")
            ]
            _amb_badge_cache[handle] = {"badges": badges, "fetched_at": now}
            return badges
    except Exception:
        # On failure, return stale cache if available, otherwise empty
        if cached:
            return cached["badges"]
        return []


CCUSAGE_STALENESS_THRESHOLD_S = 300  # 5-minute stale threshold (mirrors heuristics evaluate())


def _is_cache_stale(collected_at_unix: int | None) -> bool:
    """Return True when the cache is older than CCUSAGE_STALENESS_THRESHOLD_S.

    Uses collected_at_unix (integer epoch seconds) for a cheap, tz-safe check.
    Returns True when the value is absent or zero so callers get a safe default.
    """
    if not collected_at_unix:
        return True
    return (time.time() - collected_at_unix) > CCUSAGE_STALENESS_THRESHOLD_S


def _build_usage_response(
    cache_path: str = CCUSAGE_CACHE_PATH,
    history_limit: int = 7,
    force_refresh: bool = False,
    account_filter: str | None = None,
) -> tuple:
    """Build the response payload for GET /api/usage/current.

    Pure function (no HTTP machinery) so unit tests can call it directly.

    Args:
        cache_path:      Path to the JSON cache file written by ccusage_collector.
        history_limit:   Maximum number of history entries to return (clamped 1-50).
        force_refresh:   XACA-0890-005: kept for backward-compatible callers but
                         NO LONGER spawns ccusage_collector synchronously — see
                         the note above _ensure_collector_running() below. Both
                         True and False now just read whatever the daemon's
                         cache currently holds; the endpoint stays <50ms
                         regardless of this flag.
        account_filter:  Optional account ID to scope the totals field.
                         None (default) → all-accounts aggregate (unchanged behaviour).
                         "untagged" → totals from the untagged_bucket.
                         Any other value → totals from cache["accounts"][value].
                         When set and found, the response also gains an "account" key.
                         When set and NOT found, returns ok=False with an error message.

    Returns:
        (status_code, response_dict) tuple.
        status_code is always 200; callers must not 500 on errors so the UI
        always has something to render.
    """
    global _ccusage_missing_warned  # noqa: PLW0603

    # Clamp history_limit.
    history_limit = max(1, min(50, history_limit))

    # Self-heal: respawn the collector daemon if it has died. Cheap fast path
    # (kill -0 on the PID) when healthy; throttled detached Popen when not.
    # Runs on every request so panel polls keep the daemon alive without
    # needing a separate launchd/cron watchdog.
    _ensure_collector_running()

    # XACA-0890-005: this used to run `ccusage_collector.py --once`
    # SYNCHRONOUSLY here (subprocess.run(..., timeout=5)) whenever the
    # dashboard "refresh" button set force_refresh=True, so the button could
    # block this request for up to 5 seconds. That 5s blocking call vs. the
    # health-check's 3s curl --max-time was the original root cause of the
    # restart-loop behaviour XACA-0889 was written to investigate: a request
    # in flight here could outlive the health check's patience, making a
    # perfectly healthy-but-busy server look dead.
    #
    # Fix — approach (a), user-selected: do NOT synchronously refresh here at
    # all. _ensure_collector_running() above already keeps the daemon alive
    # (a cheap kill(pid, 0) check on the fast path, a throttled respawn only
    # if it's actually dead); force_refresh now just means "return whatever
    # the daemon's cache currently holds" and lets the daemon's own next poll
    # catch up naturally. No short-poll, no sleep-and-retry loop here — this
    # function returns immediately either way.
    #
    # This is a real, user-visible behavior change: the refresh button now
    # returns instantly instead of blocking for up to 5s, and what it
    # returns can be up to one collector poll interval old. That is not
    # hidden from the client — evaluate(cache) below computes "ok"/"stale"
    # from the cache's own collected_at timestamp (see _is_cache_stale /
    # ccusage_heuristics.evaluate), so a request that lands between polls
    # honestly reports stale=True rather than presenting old data as fresh.
    # force_refresh is intentionally unused below; kept as a parameter for
    # backward compatibility with existing callers/tests.

    # Unavailable-weekly sentinel emitted when we cannot reach evaluate_weekly.
    # Always include a "weekly" key so both UIs can unconditionally check
    # d.weekly.available rather than guarding against undefined.
    def _unavailable_weekly(reason: str) -> dict:
        return {"available": False, "reason": reason}

    # XACA-0679: empty by_model sentinel for error/pre-cache paths.
    # Mirrors _unavailable_weekly: always include the key so the frontend
    # can unconditionally read data.by_model.tiers without guarding undefined.
    # Five tiers are zero-filled; last_collected_at is empty string.
    _EMPTY_TIER = {
        "today_tokens": 0, "today_cost_usd": 0.0,
        "last_7d_tokens": 0, "last_7d_cost_usd": 0.0,
    }
    _EMPTY_BY_MODEL = {
        "tiers": {
            "Opus": dict(_EMPTY_TIER),
            "Sonnet": dict(_EMPTY_TIER),
            "Haiku": dict(_EMPTY_TIER),
            "Fable": dict(_EMPTY_TIER),
            "Other": dict(_EMPTY_TIER),
        },
        "last_collected_at": "",
    }

    # Case 1: heuristics module not importable (should not happen in prod).
    if not CCUSAGE_HEURISTICS_AVAILABLE:
        return 200, {
            "ok": False,
            "stale": True,
            "current": None,
            "projection": None,
            "calibration": None,
            "history": [],
            "totals": None,
            "weekly": _unavailable_weekly("ccusage_heuristics module not available"),
            "by_model": _EMPTY_BY_MODEL,
            "error": "ccusage_heuristics module not available",
        }

    # Case 2: cache file missing (daemon not started yet).
    if not os.path.exists(cache_path):
        if not _ccusage_missing_warned:
            print(f"[LCARS] WARNING: ccusage cache not found at {cache_path} — is the collector running?")
            _ccusage_missing_warned = True
        return 200, {
            "ok": False,
            "stale": True,
            "current": None,
            "projection": None,
            "calibration": None,
            "history": [],
            "totals": None,
            "weekly": _unavailable_weekly("collector not running"),
            "by_model": _EMPTY_BY_MODEL,
            "error": "collector not running",
        }

    # Cache file found — reset the "missing" warning flag so it fires again
    # if the collector ever stops after having run.
    _ccusage_missing_warned = False

    # Case 3: JSON parse failure.
    try:
        with open(cache_path, "r", encoding="utf-8") as _f:
            cache = json.load(_f)
    except (OSError, json.JSONDecodeError) as exc:
        print(f"[LCARS] WARNING: ccusage cache parse error: {exc}")
        return 200, {
            "ok": False,
            "stale": True,
            "current": None,
            "projection": None,
            "calibration": None,
            "history": [],
            "totals": None,
            "weekly": _unavailable_weekly(f"cache parse error: {exc}"),
            "by_model": _EMPTY_BY_MODEL,
            "error": str(exc),
        }

    # Case 4: evaluate through heuristics layer.
    result = _ccusage_heuristics.evaluate(cache)

    # Apply history_limit trim.
    if "history" in result and isinstance(result["history"], list):
        result = dict(result)
        result["history"] = result["history"][-history_limit:]

    # XACA-0250-003: append weekly heuristics as a top-level key.
    # evaluate_weekly() returns either a full weekly status dict (available=True)
    # or an unavailability sentinel (available=False).  Existing 5h consumers
    # are unaffected because we only ADD a key, never modify existing ones.
    result["weekly"] = _ccusage_heuristics.evaluate_weekly(cache)

    # XACA-0679: pass through by_model from the cache as a top-level key.
    # Schema v4 caches always have this field (all five tiers zero-filled on
    # ccusage failure).  A v3 cache (collector not yet restarted after upgrade)
    # lacks the field — fall back to _EMPTY_BY_MODEL so the frontend always
    # has a consistent shape to read without guarding undefined.
    result["by_model"] = cache.get("by_model", _EMPTY_BY_MODEL)

    # XACA-0280 Phase A.2: optional per-account totals filter.
    # When account_filter is None (default), result is returned unchanged so
    # all existing callers see exactly the same response as before.
    if account_filter is not None:
        if account_filter == "untagged":
            bucket = cache.get("untagged_bucket")
            if bucket is None:
                return 200, {
                    "ok": False,
                    "stale": False,
                    "error": "account not found: untagged",
                    "current": result.get("current"),
                    "projection": result.get("projection"),
                    "calibration": result.get("calibration"),
                    "history": result.get("history", []),
                    "totals": None,
                    "weekly": result.get("weekly"),
                    "by_model": result.get("by_model", _EMPTY_BY_MODEL),
                }
            account_totals = {
                "today_tokens": bucket.get("today_tokens", 0),
                "today_cost_usd": bucket.get("today_cost_usd", 0.0),
                "last_7d_tokens": bucket.get("last_7d_tokens", 0),
                "last_7d_cost_usd": bucket.get("last_7d_cost_usd", 0.0),
            }
            result = dict(result)
            result["totals"] = account_totals
            result["account"] = {
                "account_id": "untagged",
                "nickname": bucket.get("nickname", "Untagged (pre-isolation)"),
            }
        else:
            accounts = cache.get("accounts", {})
            acct_data = accounts.get(account_filter)
            if acct_data is None:
                return 200, {
                    "ok": False,
                    "stale": False,
                    "error": f"account not found: {account_filter}",
                    "current": result.get("current"),
                    "projection": result.get("projection"),
                    "calibration": result.get("calibration"),
                    "history": result.get("history", []),
                    "totals": None,
                    "weekly": result.get("weekly"),
                    "by_model": result.get("by_model", _EMPTY_BY_MODEL),
                }
            if not isinstance(acct_data, dict):
                return 200, {
                    "ok": False,
                    "stale": False,
                    "error": f"account data malformed: {account_filter}",
                    "current": result.get("current"),
                    "projection": result.get("projection"),
                    "calibration": result.get("calibration"),
                    "history": result.get("history", []),
                    "totals": None,
                    "weekly": result.get("weekly"),
                    "by_model": result.get("by_model", _EMPTY_BY_MODEL),
                }
            account_totals = {
                "today_tokens": acct_data.get("today_tokens", 0),
                "today_cost_usd": acct_data.get("today_cost_usd", 0.0),
                "last_7d_tokens": acct_data.get("last_7d_tokens", 0),
                "last_7d_cost_usd": acct_data.get("last_7d_cost_usd", 0.0),
            }
            result = dict(result)
            result["totals"] = account_totals
            result["account"] = {
                "account_id": account_filter,
                "nickname": acct_data.get("nickname", account_filter),
            }

    return 200, result


def _build_by_account_response(
    cache_path: str = CCUSAGE_CACHE_PATH,
) -> tuple:
    """Build the response payload for GET /api/usage/by-account — XACA-0280 Phase A.2.

    Pure function (no HTTP machinery) so unit tests can call it directly.

    Returns a flat list of per-account usage summaries plus the untagged bucket and
    all-accounts totals.  burn_rate is null in this phase — per-account burn-rate
    derivation from ccusage session data is a future follow-up.

    Args:
        cache_path:  Path to the JSON cache file written by ccusage_collector.

    Returns:
        (status_code, response_dict) tuple.
        status_code is always 200; callers must not 500 on errors so the UI
        always has something to render.
    """
    # Case 1: heuristics module not importable.
    if not CCUSAGE_HEURISTICS_AVAILABLE:
        return 200, {
            "ok": False,
            "stale": True,
            "error": "ccusage_heuristics module not available",
            "accounts": [],
            "untagged": None,
            "totals": None,
            "collected_at": None,
        }

    # Case 2: cache file missing.
    if not os.path.exists(cache_path):
        return 200, {
            "ok": False,
            "stale": True,
            "error": "collector not running",
            "accounts": [],
            "untagged": None,
            "totals": None,
            "collected_at": None,
        }

    # Case 3: JSON parse failure.
    try:
        with open(cache_path, "r", encoding="utf-8") as _f:
            cache = json.load(_f)
    except (OSError, json.JSONDecodeError) as exc:
        return 200, {
            "ok": False,
            "stale": True,
            "error": str(exc),
            "accounts": [],
            "untagged": None,
            "totals": None,
            "collected_at": None,
        }

    # Check staleness using the shared _is_cache_stale helper.
    collected_at = cache.get("collected_at")
    stale = _is_cache_stale(cache.get("collected_at_unix"))

    # Build accounts list from cache["accounts"] (schema v3).
    raw_accounts = cache.get("accounts", {})
    accounts_list = []
    for acct_id, acct_data in raw_accounts.items():
        accounts_list.append({
            "account_id": acct_id,
            "nickname": acct_data.get("nickname", acct_id),
            "tokens": acct_data.get("last_7d_tokens", 0),
            "cost_usd": acct_data.get("last_7d_cost_usd", 0.0),
            "today_tokens": acct_data.get("today_tokens", 0),
            "today_cost_usd": acct_data.get("today_cost_usd", 0.0),
            "burn_rate": None,  # Per-account burn_rate is a follow-up task
        })

    # Sort by 7-day tokens descending so the largest consumer is on top.
    accounts_list.sort(key=lambda a: a["tokens"], reverse=True)

    # Build untagged bucket summary (null when absent — v2 caches pre-XACA-0280).
    untagged = None
    untagged_raw = cache.get("untagged_bucket")
    if untagged_raw is not None:
        untagged = {
            "nickname": untagged_raw.get("nickname", "Untagged (pre-isolation)"),
            "tokens": untagged_raw.get("last_7d_tokens", 0),
            "cost_usd": untagged_raw.get("last_7d_cost_usd", 0.0),
            "today_tokens": untagged_raw.get("today_tokens", 0),
            "today_cost_usd": untagged_raw.get("today_cost_usd", 0.0),
            "cwds": untagged_raw.get("cwds", []),
        }

    # Totals are the all-accounts aggregate from the top-level cache field (v2+).
    totals = cache.get("totals")

    return 200, {
        "ok": True,
        "stale": stale,
        "collected_at": collected_at,
        "accounts": accounts_list,
        "untagged": untagged,
        "totals": totals,
    }


# XACA-0333-003: TBD sentinel values for copyright fields — server-side single source of truth.
# JS (lcars.js) mirrors this set; update both together if new placeholders are added.
_COPYRIGHT_PLACEHOLDER_VALUES: frozenset = frozenset({'<TBD-per-engagement>', '<TBD>'})


class LCARSHandler(http.server.SimpleHTTPRequestHandler):
    """Custom handler for LCARS Kanban Monitor"""

    # Path prefixes to strip (for Tailscale funnel path-based routing)
    # Note: Team names follow specific formats:
    # - Freelance: freelance-{clientId}-{projectId} (e.g., freelance-doublenode-workstats)
    # - Legal: legal-{projectId} (e.g., legal-coparenting)
    # - Medical: medical-{projectId} (e.g., medical-general)
    # - MainEvent floaters: mainevent-{projectId} (project-specific)
    #
    # XACA-0992 (round-three gate remediation): medical-general was added
    # here to match legal-coparenting and finance-personal — all three are
    # the same architectural tier (parameterized personal-team instances;
    # see _build_team_kanban_dirs() above and _PARAMETERIZED_TEMPLATES),
    # and its absence was a prior round's false completion claim (it had
    # instead added an unrelated 'medical': 'Medical' entry to
    # _BASE_BRAND_SHORT_NAMES, which does not touch funnel routing at all).
    # XACA-0628: the per-client/project freelance prefixes are no longer hardcoded
    # here — they're derived from the live team registry (TEAM_KANBAN_DIRS, which
    # is built from list_teams() incl. the per-machine overlay), so EVERY
    # overlay-only freelance project gets funnel path-stripping, not just a
    # hardcoded subset. The strip loop is order-independent (startswith match).
    PATH_PREFIXES = (
        ['/academy', '/firebase', '/dns', '/command', '/ios', '/android',
         '/mainevent', '/legal-coparenting', '/medical-general', '/finance-personal']
        + sorted(
            '/' + _t for _t in TEAM_KANBAN_DIRS
            if _t.startswith('freelance-')
        )
    )

    # XACA-0333-002: mtime-based cache for team-paths.json (avoids disk read on every GET)
    _TEAM_PATHS_CACHE: dict = {'mtime_ns': None, 'data': None}
    _TEAM_PATHS_CACHE_LOCK: threading.Lock = threading.Lock()

    # XACA-0387 (audit F-04-008): socket timeout protects each connection's
    # request thread from a slow-loris connection that would otherwise pin it
    # indefinitely. StreamRequestHandler.setup() applies this via
    # self.connection.settimeout(self.timeout).
    #
    # XACA-0890 review-gate finding (019): this comment previously described
    # "the single-threaded TCPServer" and "the lone server thread" —
    # accurate when written, stale since XACA-0890-004 swapped LCARSServer to
    # http.server.ThreadingHTTPServer. Under ThreadingHTTPServer, EVERY
    # connection gets its OWN thread (see socketserver.ThreadingMixIn.
    # process_request), so this timeout now bounds each of those per-
    # connection threads individually rather than the one shared thread the
    # single-threaded server used to run everything on. The mechanism itself
    # (self.timeout -> StreamRequestHandler.setup() -> settimeout) is
    # unchanged; only the "why it matters" framing needed correcting — a
    # slow-loris client no longer pins the ENTIRE server (that was already
    # the worse half of the old bug), it just leaks one thread until this
    # timeout fires.
    timeout = int(os.environ.get('LCARS_SOCKET_TIMEOUT', '30'))

    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=str(UI_DIR), **kwargs)

    # -----------------------------------------------------------------
    # XACA-0395: API-key auth gate. See the contract-bound module-level
    # block above (AITEAMFORGE_API_KEY_FILE et al.) for the resolve/cache
    # machinery this depends on. Deliberately NOT wired into do_OPTIONS,
    # do_GET, or do_HEAD — a gated preflight breaks every cross-origin
    # mutation in the browser UI, and GET/HEAD auth is out of scope for
    # this ticket (contract §6, entries A/B/C).
    # -----------------------------------------------------------------

    def _extract_bearer_credential(self, header_value):
        """Contract §3.1. Returns the stripped, shape-valid credential from
        an `Authorization: Bearer <key>` header value, or None if the header
        is absent, the scheme isn't Bearer, or the credential fails shape
        validation (contract §3.3). A non-Bearer scheme (e.g. Basic) is
        deliberately NOT a 401 here — it falls through so an X-API-Key
        caller behind a proxy that injects Basic isn't broken."""
        if header_value is None:
            return None
        match = _AUTH_BEARER_RE.match(header_value)
        if not match:
            return None
        credential = match.group(1).strip()
        if not _AUTH_CREDENTIAL_SHAPE_RE.match(credential):
            return None
        return credential

    def _extract_api_key_header_credential(self, header_value):
        """Contract §3.2. Returns the stripped, shape-valid credential from
        an `X-API-Key` header value, or None."""
        if header_value is None:
            return None
        credential = header_value.strip()
        if not _AUTH_CREDENTIAL_SHAPE_RE.match(credential):
            return None
        return credential

    def _extract_presented_credential(self):
        """Contract §3.4 — resolve the single presented credential from
        whichever of Authorization/X-API-Key yielded a valid-shape value.

        Header NAMES are matched case-insensitively by self.headers.get()
        (an email.message.Message subclass) by construction — no manual
        lowercasing needed.

        Returns the credential string, None (neither header yielded a
        valid-shape credential), or _AUTH_CREDENTIAL_CONFLICT (both yielded
        credentials and they disagree — caller must 401 unconditionally,
        never "try one then the other").
        """
        bearer_cred = self._extract_bearer_credential(self.headers.get('Authorization'))
        api_key_cred = self._extract_api_key_header_credential(self.headers.get('X-API-Key'))

        if bearer_cred is not None and api_key_cred is not None:
            # The equality check between the two PRESENTED values must
            # itself be constant-time (contract §3.4) — comparing with `==`
            # would reintroduce a timing oracle on the agreement path.
            if _auth_safe_equal(bearer_cred, api_key_cred):
                return bearer_cred
            return _AUTH_CREDENTIAL_CONFLICT

        return bearer_cred if bearer_cred is not None else api_key_cred

    def _cors_request_headers(self):
        """Return (Host, Origin) for this request, tolerating a handler with
        no usable `headers` mapping.

        XACA-0401 follow-up: the code this replaced was
        `send_header('Access-Control-Allow-Origin', '*')` — a constant that
        touched no request state and therefore could not fail. Reading
        `self.headers` reintroduced a way for HEADER EMISSION to raise, and an
        AttributeError here surfaces as a 500 on a request that would
        otherwise have succeeded (observed in CI: serve_calendar_items and
        handle_delete_epic both turned 200 -> 500 against handlers built
        without `headers`).

        A response-header helper must never be the thing that fails a
        response. Missing/!unusable headers degrade to (None, None), which
        _resolve_cors_origin() maps to "omit the header" — the same
        fail-closed outcome as an untrusted origin, never a wildcard.
        """
        headers = getattr(self, 'headers', None)
        if headers is None:
            return None, None
        getter = getattr(headers, 'get', None)
        if not callable(getter):
            return None, None
        try:
            return getter('Host'), getter('Origin')
        except Exception:
            return None, None

    def _send_cors_headers(self):
        """XACA-0401 — emit the CORS headers for this request.

        Replaces `send_header('Access-Control-Allow-Origin', '*')`. Emits
        nothing at all when the origin does not resolve (fail closed).

        `Vary: Origin` is emitted whenever ACAO is, and is NOT optional: the
        response body for a given URL is now origin-dependent, so an
        intermediary that caches without varying could hand one origin's
        response to another.

        MUST NOT be called from serve_auth_key() — that handler's deliberate
        absence of any ACAO header is load-bearing. See the block comment on
        _origin_matches_host().
        """
        host, origin = self._cors_request_headers()
        allowed = _resolve_cors_origin(host, origin)

        # XACA-0401 review finding 016 — `Vary: Origin` is emitted on EVERY
        # path, not only alongside ACAO. The response for a given URL is now
        # origin-dependent whether or not the header is granted, so the
        # REFUSED response needs the same cache key; most of these endpoints
        # send `Cache-Control: no-cache` (revalidate), not `no-store`, so an
        # origin-blind intermediary could otherwise store the header-less
        # variant and replay it to a legitimate origin. do_OPTIONS() and
        # serve_auth_key() already varied unconditionally — this helper, the
        # one 53 sites depend on, did not. That inconsistency was the bug.
        self.send_header('Vary', 'Origin')
        if allowed is None:
            _log_cors_refusal(host, origin)
            return
        self.send_header('Access-Control-Allow-Origin', allowed)

    def _send_auth_401(self):
        """Contract §4 — byte-exact 401. Deliberately does NOT reuse
        _send_json_response(): that helper emits `Content-Type: application/
        json` with no charset and uses json.dumps()'s default (non-compact)
        separators, so its bytes would not match the fleet-monitor side's
        res.json() output. The body here is a fixed constant regardless of
        rejection reason (absent / wrong / malformed / disagreeing headers)
        — that is the non-leak requirement, and it's what makes the 401
        byte-identical across all rejection paths testable."""
        body = _AUTH_401_BODY
        self.send_response(401)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self._send_cors_headers()
        self.send_header('WWW-Authenticate', 'Bearer')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _auth_gate(self) -> bool:
        """XACA-0395 central auth gate. Call as the FIRST statement of every
        state-mutating dispatcher (do_POST/do_PUT/do_PATCH/do_DELETE) —
        before reading any request body (contract: reject unauthenticated
        callers before an unbounded rfile.read()).

        Returns True if the request may proceed. Returns False if a 401 has
        already been written to the wire; the caller MUST return
        immediately and do nothing else.
        """
        try:
            parsed_path = urlparse(self.path).path
        except Exception:
            parsed_path = self.path
        if (self.command, parsed_path) in _PUBLIC_MUTATING_ROUTES:
            return True

        expected_key, _rejected_for_mode = _get_resolved_api_key()
        if not expected_key:
            # Open posture (contract §7): no key configured on this
            # machine. Every request proceeds exactly as it does today.
            return True

        presented = self._extract_presented_credential()
        if presented is None or presented is _AUTH_CREDENTIAL_CONFLICT:
            self._send_auth_401()
            return False

        if not _auth_safe_equal(presented, expected_key):
            self._send_auth_401()
            return False

        return True

    # -----------------------------------------------------------------
    # XACA-0161-003 — terminal bridge (discovery, ticket mint, ws proxy).
    #
    # READ docs/xaca-0161-terminal-bridge-evaluation.md §5, §6.4 and §6.5
    # before touching anything below. The short version:
    #
    #   * A WebSocket handshake is a GET, and _auth_gate() is NOT wired into
    #     do_GET. Nothing above this comment authenticates the ws route —
    #     the checks in serve_terminal_ws() are the only ones there are.
    #   * _auth_gate() FAILS OPEN with no API key configured. These routes
    #     fail CLOSED instead. That divergence is the point, not an
    #     inconsistency to tidy up.
    #   * `ttyd -W` is a writable shell. Every refusal below is a refusal to
    #     hand a caller remote code execution.
    # -----------------------------------------------------------------

    def _terminal_audit(self, event: str, **fields):
        """One-line audit record for every terminal decision (threat model
        §6.6: "Every bridge connection: timestamp, source address, session.
        Cheap now, invaluable during an incident").

        NEVER pass a ticket, an API key, or any part of either. The caller
        controls what lands here; keep it to identifiers and outcomes.
        """
        try:
            source = self.client_address[0]
        except (AttributeError, IndexError, TypeError):
            source = '?'
        detail = ' '.join(f"{k}={v}" for k, v in fields.items())
        print(f"[LCARS] TERMINAL {event} src={source} {detail}".rstrip(), flush=True)

    def _terminal_refuse(self, status: int, reason: str, message: str = None):
        """Refuse a terminal request, audit it, and return.

        The client-visible message is deliberately coarse while the audited
        `reason` is specific: an attacker probing the ws route should not be
        able to tell "expired ticket" from "ticket for another terminal" from
        "no such terminal", but an operator reading the log must.
        """
        self._terminal_audit('REFUSE', reason=reason, status=status)
        self._send_json_response({"error": message or "Terminal request refused"}, status)

    def _terminal_gate(self) -> bool:
        """Common precondition for ALL three terminal routes. False means a
        response has already been written and the caller must return."""
        if not TERMINAL_BRIDGE_AVAILABLE or not _lcars_terminal.terminal_enabled():
            # 404 rather than 503: a machine that has not opted in should not
            # confirm that a shell endpoint exists here at all. The feature is
            # off by default on every machine in the fleet.
            self._send_json_response({"error": "Not found"}, 404)
            return False

        key, _rejected_for_mode = _get_resolved_api_key()
        if not key:
            # THE DELIBERATE DIVERGENCE (evaluation §5 conclusion 3, §6.4
            # item 3). _auth_gate() returns True here — open posture — and for
            # a kanban board that is a considered trade-off. For an
            # interactive writable shell it is remote code execution for
            # anyone who can reach the port. There is no acceptable degraded
            # mode, so the route refuses to serve rather than serving
            # unauthenticated.
            self._terminal_audit('REFUSE', reason='no-api-key-configured', status=503)
            self._send_json_response({
                "error": "Terminal bridge refuses to serve without an API key",
                "detail": (
                    "No AITEAMFORGE_API_KEY is configured on this machine. The "
                    "terminal routes fail closed rather than following the "
                    "open posture the rest of the server uses, because an "
                    "unauthenticated terminal is an unauthenticated shell. "
                    "Provision ~/.aiteamforge/api-key (regular file, mode 0600) "
                    "and restart."
                ),
            }, 503)
            return False
        return True

    def _terminal_host_origin_ok(self) -> bool:
        """Host allowlist + Origin check for terminal routes.

        Browsers DO send `Origin` on a WebSocket upgrade — threat model §6.3
        calls this "one place the check has teeth" — so this is the control
        that stops a foreign page in an already-authenticated browser from
        opening a shell socket with a stolen ticket. `Host` is checked first
        because Origin-vs-Host compares two attacker-supplied values and is
        blind to DNS rebinding on its own (see _origin_matches_host()).
        """
        host = self.headers.get('Host', '')
        if not _host_is_local_identity(host):
            self._terminal_refuse(403, 'host-not-local-identity', "Forbidden")
            return False
        origin = self.headers.get('Origin')
        if origin and not _origin_matches_host(origin, host):
            self._terminal_refuse(403, 'origin-mismatch', "Forbidden")
            return False
        return True

    def _terminal_credential_ok(self) -> bool:
        """GET-scoped credential check, for routes that a browser reaches with
        an ordinary fetch() and can therefore attach a header to.

        This is NOT reusable for the WebSocket route: the browser WebSocket
        constructor cannot set headers (evaluation §3.4), which is precisely
        why that route uses a ticket instead. Discovery is a plain XHR, so it
        gets the strong check.
        """
        expected_key, _rejected_for_mode = _get_resolved_api_key()
        if not expected_key:
            # Unreachable via _terminal_gate(), but never assume a caller
            # ordered the checks correctly.
            self._terminal_refuse(503, 'no-api-key-configured')
            return False
        presented = self._extract_presented_credential()
        if presented is None or presented is _AUTH_CREDENTIAL_CONFLICT:
            self._terminal_audit('REFUSE', reason='no-credential', status=401)
            self._send_auth_401()
            return False
        if not _auth_safe_equal(presented, expected_key):
            self._terminal_audit('REFUSE', reason='bad-credential', status=401)
            self._send_auth_401()
            return False
        return True

    def _terminal_lcars_port(self):
        """Port this server is actually bound to.

        Read from the live socket rather than a global set in main(), so the
        derived ttyd ports are correct for whatever instance is running —
        including a throwaway test instance on an arbitrary port.
        """
        try:
            return int(self.server.server_address[1])
        except (AttributeError, IndexError, TypeError, ValueError):
            return None

    def _terminal_board_terminals(self):
        """The current team's `terminals` map, or {} when unreadable."""
        try:
            board_file = get_board_file(LCARS_TEAM)
            with open(board_file, 'r', encoding='utf-8') as handle:
                board = json.load(handle)
        except (OSError, ValueError, TypeError):
            return {}
        if not isinstance(board, dict):
            return {}
        terminals = board.get('terminals', {})
        return terminals if isinstance(terminals, dict) else {}

    def serve_terminals_list(self):
        """GET /api/terminals — discovery.

        GATED, and here is the justification the subitem asked for. The
        response names every terminal on this machine and the loopback port
        each shell listens on. That is a map of exactly which ports an
        attacker who lands any local code execution should dial — precisely
        the topology the loopback binding exists to keep private. `_auth_gate()`
        does not cover GET, so the gate is written out explicitly above; the
        cost is that the PWA must attach `X-API-Key` to this fetch, which it
        can (unlike the WebSocket handshake) and already does for other calls.
        The alternative — an open discovery endpoint "because the names aren't
        secret" — trades a real disclosure for zero convenience.
        """
        if not self._terminal_gate():
            return
        if not self._terminal_host_origin_ok():
            return
        if not self._terminal_credential_ok():
            return

        lcars_port = self._terminal_lcars_port()
        if lcars_port is None:
            self._terminal_refuse(503, 'unknown-lcars-port')
            return

        board_terminals = self._terminal_board_terminals()
        entries = []
        for name in _lcars_terminal.terminal_names(board_terminals):
            try:
                ttyd_port = _lcars_terminal.resolve_ttyd_port(lcars_port, board_terminals, name)
            except _lcars_terminal.TerminalConfigError as exc:
                # A board with more terminals than the block allows, or a
                # dashboard port outside the derivation band. Surface it —
                # silently omitting the terminal would look like a UI bug.
                entries.append({"name": name, "available": False, "error": str(exc)})
                continue
            info = board_terminals.get(name) or {}
            entries.append({
                "name": name,
                "available": True,
                "developer": info.get('developer'),
                "avatar": info.get('avatar'),
                "role": info.get('role'),
                "color": info.get('color'),
                "ttydPort": ttyd_port,
                # wsPath is authoritative. A full wsUrl is NOT returned: this
                # backend cannot know its own external scheme (it speaks plain
                # HTTP even behind an HTTPS-terminating Tailscale Serve — see
                # _origin_matches_host()), so any wss:// URL it composed would
                # be a guess. The client builds it from location.* instead,
                # which is the only place the real scheme is known.
                "wsPath": f"/terminal/{name}/ws",
            })

        self._send_json_response({
            "team": LCARS_TEAM,
            "lcarsPort": lcars_port,
            "terminals": entries,
            "maxSessions": _lcars_terminal.max_sessions(),
            "activeSessions": _TERMINAL_SESSIONS.active,
            "ticketTtlSeconds": _lcars_terminal.ticket_ttl_seconds(),
            "ticketPath": "/api/terminal/ticket",
        })

    def handle_terminal_ticket(self):
        """POST /api/terminal/ticket {"terminal": "engineering"} — mint.

        This is the root of trust for the whole feature (evaluation §6.4
        item 1). It is a POST, so do_POST's `_auth_gate()` has already run
        with the full Bearer/X-API-Key check — and `_terminal_gate()` below
        closes that gate's fail-open hole for this route.
        """
        # DRAIN THE BODY BEFORE ANY REFUSAL — this ordering is load-bearing and
        # it is not stylistic. Every refusal below writes a response and then
        # lets the connection close. If an unread request body is still sitting
        # in the socket at that point, macOS answers the close with an RST
        # instead of a FIN, and the client raises ConnectionResetError while
        # reading a response the server had already written correctly. The
        # caller never learns WHY it was refused — it sees a reset connection,
        # which reads as "the server crashed", not "you are not authorised".
        #
        # Found as an intermittent (~1-in-6) failure in this subitem's own test
        # suite, on the two refusal paths that skipped the read: the 404 when
        # the feature is disabled and the 503 when no API key is configured.
        # Reading first is safe: do_POST has already applied _auth_gate() and
        # capped Content-Length at MAX_POST_BODY_BYTES before dispatch, so this
        # read is bounded and no less authenticated than every other POST route.
        raw = self._terminal_drain_request_body()

        if not self._terminal_gate():
            return
        if not self._terminal_host_origin_ok():
            return

        try:
            payload = json.loads(raw.decode('utf-8')) if raw else {}
        except (ValueError, UnicodeDecodeError):
            self._terminal_refuse(400, 'malformed-body', "Invalid JSON body")
            return
        if not isinstance(payload, dict):
            self._terminal_refuse(400, 'malformed-body', "Invalid JSON body")
            return

        terminal = payload.get('terminal')
        if not isinstance(terminal, str) or not _lcars_terminal.TERMINAL_NAME_RE.match(terminal):
            self._terminal_refuse(400, 'bad-terminal-name', "Invalid terminal name")
            return

        lcars_port = self._terminal_lcars_port()
        if lcars_port is None:
            self._terminal_refuse(503, 'unknown-lcars-port')
            return

        board_terminals = self._terminal_board_terminals()
        try:
            # Resolve now so a ticket is never minted for a terminal that
            # cannot possibly be dialled.
            _lcars_terminal.resolve_ttyd_port(lcars_port, board_terminals, terminal)
        except _lcars_terminal.TerminalConfigError:
            self._terminal_refuse(404, 'unknown-terminal', "Unknown terminal")
            return

        ticket, ttl = _TERMINAL_TICKETS.mint(terminal)
        self._terminal_audit('MINT', terminal=terminal, ttl=ttl)
        self._send_json_response({
            "terminal": terminal,
            "ticket": ticket,
            "expiresInSeconds": ttl,
            "wsPath": f"/terminal/{terminal}/ws",
        })

    def _terminal_drain_request_body(self) -> bytes:
        """Read the declared request body off the socket, always.

        See the call site in handle_terminal_ticket() for why this must happen
        BEFORE any refusal is written: an unread body turns the connection
        close into an RST and the client loses the response it was about to
        read. Returns b'' on any read failure — a body we could not read is a
        body the caller will be refused over anyway.

        Bounded by do_POST's MAX_POST_BODY_BYTES check, which has already run.
        """
        try:
            length = int(self.headers.get('Content-Length') or 0)
        except (TypeError, ValueError):
            return b''
        if length <= 0:
            return b''
        try:
            return self.rfile.read(length)
        except OSError:
            return b''

    def _terminal_resolve_port(self, terminal: str):
        """Shared precondition for every /terminal/<name>/* route. Returns the
        ttyd port, or None when a refusal has already been written."""
        lcars_port = self._terminal_lcars_port()
        if lcars_port is None:
            self._terminal_refuse(503, 'unknown-lcars-port')
            return None
        try:
            return _lcars_terminal.resolve_ttyd_port(
                lcars_port, self._terminal_board_terminals(), terminal)
        except _lcars_terminal.TerminalConfigError:
            self._terminal_refuse(404, 'unknown-terminal', "Unknown terminal")
            return None

    def _terminal_redeem(self, terminal: str, query: str) -> bool:
        """Validate and BURN the single-use ticket from the query string.

        False means a 401 has been written. One generic refusal covers
        expired / unknown / reused / wrong-terminal / malformed, so a caller
        cannot use the response to distinguish them; the audit line records
        only that it failed, never the presented value.
        """
        values = parse_qs(query or '').get('ticket') or []
        ticket = values[0] if len(values) == 1 else ''
        if _TERMINAL_TICKETS.redeem(ticket, terminal):
            return True
        self._terminal_audit('REFUSE', reason='ticket-rejected',
                             terminal=terminal, status=401)
        self._send_auth_401()
        return False

    def serve_terminal_asset(self, terminal: str, leaf: str, query: str):
        """GET /terminal/<name>/ and /terminal/<name>/token — buffered proxy.

        These exist because ttyd serves them and XACA-0161-002 starts ttyd
        with `-b /terminal/<name>`. Measured against live ttyd 1.7.7: with
        `-H X-WEBAUTH-USER` both return **407** unless the header is present
        AND non-empty, so the header must be injected here too — not only on
        the upgrade. `/token` itself is a no-op (`{"token": ""}` with no `-c`);
        ttyd's in-band token is not, and must never be treated as, the gate.

        Ticketed exactly like the upgrade. A client needing index + token +
        socket mints three tickets. That is the cost of single-use, and
        single-use is the property that makes a URL-borne credential
        acceptable at all.
        """
        if not self._terminal_gate():
            return
        if not self._terminal_host_origin_ok():
            return
        ttyd_port = self._terminal_resolve_port(terminal)
        if ttyd_port is None:
            return
        if not self._terminal_redeem(terminal, query):
            return

        upstream_path = f"{_TERMINAL_ROUTE_PREFIX}{terminal}/{leaf}"
        try:
            status, headers, body = _lcars_terminal.proxy_buffered_get(
                _lcars_terminal.ttyd_host(), ttyd_port, upstream_path,
                _lcars_terminal.webauth_user())
        except (_lcars_terminal.HandshakeError, OSError):
            self._terminal_refuse(502, 'upstream-unreachable', "Terminal backend unavailable")
            return

        if status != 200:
            # ttyd's 407 body (or any other non-200) is NOT relayed: a 407 here
            # means the injected header failed ttyd's own check, which is a
            # server misconfiguration, not something to hand the client.
            self._terminal_refuse(502, f'upstream-status-{status}',
                                  "Terminal backend refused the request")
            return

        self._terminal_audit('ASSET', terminal=terminal, leaf=leaf or 'index',
                             bytes=len(body))
        self.send_response(200)
        for name, value in headers:
            self.send_header(name, value)
        self._send_cors_headers()
        # ttyd's index embeds the client for a live shell — never let an
        # intermediary or the browser keep a copy.
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def serve_terminal_ws(self, terminal: str, query: str):
        """GET /terminal/<name>/ws?ticket=<nonce> — redeem, then relay.

        THE ONLY HIJACK PATH IN THIS FILE. Ordering below is load-bearing:
        every refusal happens BEFORE the socket leaves the handler's control,
        because once bytes of a relayed 101 are on the wire there is no way to
        send an HTTP error instead.
        """
        if not self._terminal_gate():
            return
        if not self._terminal_host_origin_ok():
            return

        # Only a genuine upgrade may reach the hijack. A plain GET that landed
        # on this route is refused with an ordinary HTTP response while that
        # is still possible.
        if not _lcars_terminal.is_websocket_upgrade(self.headers):
            self._terminal_refuse(400, 'not-a-websocket-upgrade', "Expected a WebSocket upgrade")
            return

        ttyd_port = self._terminal_resolve_port(terminal)
        if ttyd_port is None:
            return

        # Ticket BEFORE the session cap. XACA-0161 PR #776 review finding:
        # the original order acquired the cap first, so that a refusal at the
        # cap would not burn the caller's single-use nonce. That is a real
        # convenience, but it made the cap consumable by a caller with NO
        # credential and NO ticket -- anyone who could reach the route could
        # exhaust every slot and deny the feature to authenticated users. A
        # pre-auth denial-of-service is a worse defect than making a legitimate
        # user mint a second nonce, and minting is cheap and already gated by
        # `_auth_gate()`, so the client simply re-mints (it re-mints on every
        # reconnect regardless).
        #
        # Redeem is validate-AND-burn under one lock, so there is no window
        # here for two callers to both pass before either burns.
        if not self._terminal_redeem(terminal, query):
            return

        # The cap itself is mandatory: each pane pins a thread for its lifetime
        # on a server whose unbounded thread creation is a recorded open issue.
        if not _TERMINAL_SESSIONS.acquire():
            self._terminal_refuse(503, 'session-cap-reached',
                                  "Too many active terminal sessions")
            return

        try:

            try:
                upstream = _lcars_terminal.connect_upstream(
                    _lcars_terminal.ttyd_host(), ttyd_port)
            except OSError:
                # The upstream reason (refused / no route / timeout) is audited
                # but not returned: it tells a caller which loopback ports have
                # a live shell behind them.
                self._terminal_refuse(502, 'upstream-unreachable', "Terminal backend unavailable")
                return

            try:
                request_path = f"{_TERMINAL_ROUTE_PREFIX}{terminal}/ws"
                handshake = _lcars_terminal.build_upstream_handshake(
                    request_path, self.headers,
                    _lcars_terminal.ttyd_host(), ttyd_port,
                    _lcars_terminal.webauth_user())
                upstream.sendall(handshake)
                head, status, upstream_residue = _lcars_terminal.read_upstream_head(upstream)
            except (_lcars_terminal.HandshakeError, OSError):
                self._terminal_refuse(502, 'upstream-handshake-failed',
                                      "Terminal backend unavailable")
                upstream.close()
                return

            if status != 101:
                # ttyd's own error body is NOT relayed — it would leak upstream
                # detail to an unauthenticated-shaped caller.
                self._terminal_refuse(502, 'upstream-refused-upgrade',
                                      "Terminal backend refused the connection")
                upstream.close()
                return

            # ---- POINT OF NO RETURN -------------------------------------
            # Past here the socket is ours. No send_response(), no
            # _send_json_response(), no send_error(): all three would emit
            # Server:/Date: headers and an access-log line into what is now a
            # WebSocket stream (evaluation §6.5 item 6). The 101 is relayed
            # verbatim from ttyd instead.
            #
            # close_connection stops handle_one_request()'s keep-alive loop
            # from trying to parse another request off a socket that now
            # carries WebSocket frames (§6.5 item 4).
            self.close_connection = True

            # §6.5 item 2 — bytes a client pipelined after its handshake are
            # already inside rfile's buffer and are invisible to select() on
            # the raw socket. Drain them, or lose them.
            residue = _lcars_terminal.drain_buffered_reader(self.connection, self.rfile)

            self._terminal_audit('OPEN', terminal=terminal, ttyd_port=ttyd_port,
                                 active=_TERMINAL_SESSIONS.active)
            try:
                c2u, u2c, reason = _lcars_terminal.pump(
                    self.connection, upstream,
                    initial_to_upstream=residue,
                    initial_to_client=head + upstream_residue,
                    idle_timeout=_lcars_terminal.idle_timeout_seconds(),
                )
            finally:
                try:
                    upstream.close()
                except OSError:
                    pass
            self._terminal_audit('CLOSE', terminal=terminal, reason=reason,
                                 c2u=c2u, u2c=u2c)
        finally:
            # Released on EVERY path, including the hijacked one — a leaked
            # slot here would silently shrink the cap to zero over time and
            # look like "terminals stopped working".
            _TERMINAL_SESSIONS.release()

    def do_OPTIONS(self):
        """Handle CORS preflight requests.

        XACA-0395-007 P1 CORRECTION (post-review): subitem 003 widened this to
        'Content-Type, Authorization, X-API-Key' per plan D7, reasoning it was
        harmless preventive hygiene since zero legitimate cross-origin mutating
        callers existed at the time. That reasoning missed a second-order
        effect: this handler is the SINGLE, path-independent preflight
        responder for every cross-origin request reaching this server,
        including a mutating one — so widening it here is what allows a
        foreign origin's preflighted POST/PUT/PATCH/DELETE carrying
        `Authorization`/`X-API-Key` to pass, which is a necessary step in the
        cross-origin key-theft-then-mutate chain that motivated the
        GET /api/auth-key origin check above. Re-verified before reverting
        (not merely re-asserting D7's now-stale finding): a repo-wide sweep
        for cross-port fetches in lcars-ui/ still finds exactly the same two
        hits D7 found (redirect.html:164, agent-panel-router.html:97 — both
        GET /api/status, both already allowlisted, neither mutating), and
        fleet-monitor's own bundled /lcars dashboard (server.js `app.use('/lcars',
        express.static(...))`) is a static copy served from fleet-monitor's OWN
        origin with zero fetch() calls back to a live per-team LCARS instance
        on another port — it is not a cross-origin proxy for this API. No
        legitimate cross-origin authenticated caller exists. Reverted to
        'Content-Type' only (pre-ticket value) — same-origin requests never
        trigger a CORS preflight regardless of what this header allows, so the
        86 in-page mutating fetches are unaffected either way.

        XACA-0401: the preflight response is now origin-conditional. When
        _resolve_cors_origin() refuses the caller, this handler still answers
        200 (an OPTIONS request is legal and the browser is entitled to a
        reply) but advertises NOTHING: no Allow-Origin, and critically no
        Allow-Methods. Advertising 'POST, PUT, PATCH, DELETE' to an origin we
        are about to refuse is pure disclosure — the browser blocks the real
        request anyway once ACAO is absent, so the method list is only ever
        read by a caller deciding what to try next. Allow-Headers stays
        pinned to 'Content-Type'; do NOT widen it (see the P1 CORRECTION
        above — that widening was reverted for a documented reason).
        """
        self.send_response(200)
        # XACA-0401 finding 016: now that _send_cors_headers() varies on every
        # path, this handler no longer needs its own copy of the resolution
        # flow — it delegates and adds only the preflight-specific grants.
        host, origin = self._cors_request_headers()
        self._send_cors_headers()
        if _resolve_cors_origin(host, origin) is not None:
            self.send_header('Access-Control-Allow-Methods',
                             'GET, POST, PUT, PATCH, DELETE, OPTIONS')
            self.send_header('Access-Control-Allow-Headers', 'Content-Type')
        self.end_headers()

    def do_POST(self):
        """Handle POST requests"""
        # XACA-0395: reject unauthenticated callers before reading (or even
        # bounds-checking) any request body — this MUST stay the first
        # statement in do_POST.
        if not self._auth_gate():
            return

        # XACA-0387 (audit F-04-008): cap the declared body size before dispatch so a
        # forged/oversized Content-Length cannot drive an unbounded rfile.read().
        cl_header = self.headers.get('Content-Length')
        if cl_header is not None:
            try:
                declared_len = int(cl_header)
            except (TypeError, ValueError):
                self._send_json_response({"error": "Invalid Content-Length header"}, 400)
                return
            if declared_len < 0:
                self._send_json_response({"error": "Invalid Content-Length header"}, 400)
                return
            if declared_len > MAX_POST_BODY_BYTES:
                self._send_json_response(
                    {"error": f"Request body too large (max {MAX_POST_BODY_BYTES} bytes)"}, 413)
                return

        parsed = urlparse(self.path)
        path = parsed.path

        # Strip known path prefixes for Tailscale funnel compatibility
        for prefix in self.PATH_PREFIXES:
            if path.startswith(prefix + '/'):
                path = path[len(prefix):] or '/'
                break

        # XACA-0161-003: ticket mint. A POST specifically so the existing
        # _auth_gate() above already applied the Bearer/X-API-Key check —
        # this route is the root of trust for the WebSocket ticket.
        if path == '/api/terminal/ticket':
            self.handle_terminal_ticket()
            return

        if path == '/api/toggle-collapsed':
            self.handle_toggle_collapsed()
        elif path == '/api/roadmap-pdf':
            self.handle_roadmap_pdf_stash()
        elif path == '/api/update-item':
            self.handle_update_item()
        elif path == '/api/update-subitem':
            self.handle_update_subitem()
        # Integration API endpoints
        elif path == '/api/integrations/search':
            self.handle_integration_search()
        elif path == '/api/integrations/verify':
            self.handle_integration_verify()
        elif path == '/api/integrations/test':
            self.handle_integration_test()
        elif path == '/api/integrations/save':
            self.handle_integration_save()
        elif path == '/api/integrations/delete':
            self.handle_integration_delete()
        elif path == '/api/integrations/boards':
            self.handle_integration_boards()
        elif path == '/api/integrations/create-item':
            self.handle_integration_create_item()
        # Sync API endpoints
        elif path == '/api/sync/item':
            self.handle_sync_item()
        elif path == '/api/sync/board':
            self.handle_sync_board()
        # Import API endpoints
        elif path == '/api/import/fetch':
            self.handle_import_fetch()
        elif path == '/api/import/execute':
            self.handle_import_execute()
        # Release API endpoints
        elif path == '/api/releases':
            self.handle_create_release()
        elif path.startswith('/api/releases/') and path.endswith('/items'):
            release_id = path.replace('/api/releases/', '').replace('/items', '')
            self.handle_assign_item_to_release(release_id)
        elif path.startswith('/api/releases/') and path.endswith('/crs'):
            # POST /api/releases/<id>/crs — link a CR to the release (XACA-0657)
            release_id = path[len('/api/releases/'):-len('/crs')]
            self.handle_link_cr_to_release(release_id)
        elif path.startswith('/api/releases/') and path.endswith('/platform-gate-status'):
            # POST /api/releases/<id>/platform-gate-status — persist gate result (XACA-0658-004)
            release_id = path[len('/api/releases/'):-len('/platform-gate-status')]
            self.handle_platform_gate_status(release_id)
        elif path.startswith('/api/releases/') and path.endswith('/promote'):
            release_id = path.replace('/api/releases/', '').replace('/promote', '')
            self.handle_promote_release(release_id)
        elif path.startswith('/api/releases/') and path.endswith('/plan'):
            # POST /api/releases/<id>/plan — demote all platforms to PLANNED (XACA-0729)
            release_id = path[len('/api/releases/'):-len('/plan')]
            self.handle_plan_release(release_id)
        elif path == '/api/releases/flow-config':
            self.handle_update_flow_config()
        elif path == '/api/releases/sync-item':
            self.handle_sync_item_to_release()
        elif path == '/api/releases/sync-all':
            self.handle_sync_all_to_releases()
        # Epic API endpoints
        elif path == '/api/epics':
            self.handle_create_epic()
        elif path.startswith('/api/epics/') and path.endswith('/items'):
            epic_id = path.replace('/api/epics/', '').replace('/items', '')
            self.handle_assign_item_to_epic(epic_id)
        # Todo API endpoints
        elif path == '/api/todos':
            self.handle_create_todo()
        # Calendar sync API endpoints
        elif path == '/api/calendar/config':
            self.handle_save_calendar_config()
        elif path == '/api/calendar/connect/apple':
            self.handle_connect_apple_calendar()
        elif path == '/api/calendar/connect/google':
            self.handle_connect_google_calendar()
        elif path.startswith('/api/calendar/disconnect/'):
            provider = path.replace('/api/calendar/disconnect/', '')
            self.handle_disconnect_calendar(provider)
        elif path == '/api/calendar/sync/trigger':
            self.handle_trigger_calendar_sync()
        elif path == '/api/calendar/conflicts/resolve':
            self.handle_resolve_calendar_conflict()
        elif path == '/api/terminal/activate':
            self.handle_terminal_activate()
        # Team Export/Import API endpoints
        elif path == '/api/export/create':
            self.handle_create_export()
        elif path == '/api/export/secrets/create':
            self.handle_create_secrets_export()
        elif path == '/api/import/upload':
            self.handle_import_upload()
        elif path.startswith('/api/import/apply/'):
            job_id = path.replace('/api/import/apply/', '')
            self.handle_import_apply(job_id)
        # Secrets Import API endpoints (XACA-0172-003)
        elif path == '/api/import/secrets/upload':
            self.handle_secrets_import_upload()
        elif path.startswith('/api/import/secrets/preflight/'):
            job_id = path.replace('/api/import/secrets/preflight/', '')
            self.handle_secrets_import_preflight(job_id)
        elif path.startswith('/api/import/secrets/apply/'):
            job_id = path.replace('/api/import/secrets/apply/', '')
            self.handle_secrets_import_apply(job_id)
        # RAG Engine API endpoints
        elif path == '/api/rag-engines/save':
            self.handle_rag_engine_save()
        elif path == '/api/rag-engines/delete':
            self.handle_rag_engine_delete()
        elif path == '/api/rag-engines/install':
            self.handle_rag_engine_install()
        elif path == '/api/rag-engines/uninstall':
            self.handle_rag_engine_uninstall()
        elif path == '/api/rag-engines/start':
            self.handle_rag_engine_start()
        elif path == '/api/rag-engines/stop':
            self.handle_rag_engine_stop()
        elif path == '/api/rag-engines/health':
            self.handle_rag_engine_health()
        elif path == '/api/rag-engines/configure':
            self.handle_rag_engine_configure()
        elif path == '/api/rag-engines/check-updates':
            self.handle_rag_engine_check_updates()
        elif path == '/api/rag-engines/update':
            self.handle_rag_engine_update()
        # Graph API endpoints
        elif path == '/api/graph/data':
            self.handle_graph_data()
        elif path == '/api/graph/query':
            self.handle_graph_query()
        elif path == '/api/graph/node':
            self.handle_graph_node()
        # Weekly anchor API endpoints (XACA-0253-003)
        elif path == '/api/weekly-anchor':
            self.handle_post_weekly_anchor()
        # XACA-0292: Team config (CR/CAB support flag)
        elif path == '/api/team-config':
            self.handle_update_team_config()
        # XACA-0281 Phase A.3: Team account config endpoints
        elif path == '/api/team-config/account/save':
            self.handle_team_account_save()
        elif path == '/api/team-config/account/test-connection':
            self.handle_team_account_test_connection()
        # === XACA-0281: AI engines registry consumer ===
        elif path == '/api/team-config/account/assign':
            self.handle_team_account_assign()
        # XACA-0281 Phase A.3: Resume-ID management
        elif path == '/api/team-config/account/resume-ids':
            self.handle_team_account_resume_ids()
        # CR transition endpoint (XACA-0328-005)
        elif path.startswith('/api/kanban/cr/') and path.endswith('/transition'):
            cr_id = path[len('/api/kanban/cr/'):-len('/transition')]
            self.handle_cr_transition(cr_id)
        # Alert ingestion endpoints (XACA-0334-002)
        elif path == '/api/alerts':
            self.handle_create_alert()
        elif path.startswith('/api/alerts/') and path.endswith('/dismiss'):
            alert_id = path[len('/api/alerts/'):-len('/dismiss')]
            self.handle_dismiss_alert(alert_id)
        else:
            self.send_error(404, f"Unknown POST endpoint: {path}")

    def do_PUT(self):
        """Handle PUT requests"""
        # XACA-0395: central auth gate — must stay the first statement.
        if not self._auth_gate():
            return

        parsed = urlparse(self.path)
        path = parsed.path

        # Strip known path prefixes for Tailscale funnel compatibility
        for prefix in self.PATH_PREFIXES:
            if path.startswith(prefix + '/'):
                path = path[len(prefix):] or '/'
                break

        # Release API endpoints
        if path.startswith('/api/releases/') and not path.endswith('/items') and not path.endswith('/promote') and not path.endswith('/platform-gate-status'):
            release_id = path.replace('/api/releases/', '')
            self.handle_update_release(release_id)
        # Epic API endpoints
        elif path.startswith('/api/epics/') and not path.endswith('/items'):
            epic_id = path.replace('/api/epics/', '')
            self.handle_update_epic(epic_id)
        # Todo API endpoints
        elif path == '/api/todos':
            self.handle_update_todo()
        else:
            self.send_error(404, f"Unknown PUT endpoint: {path}")

    def do_PATCH(self):
        """Handle PATCH requests"""
        # XACA-0395: central auth gate — must stay the first statement.
        if not self._auth_gate():
            return

        parsed = urlparse(self.path)
        path = parsed.path

        # Strip known path prefixes for Tailscale funnel compatibility
        for prefix in self.PATH_PREFIXES:
            if path.startswith(prefix + '/'):
                path = path[len(prefix):] or '/'
                break

        # Release API endpoints
        if path.startswith('/api/releases/') and path.endswith('/archive'):
            release_id = path.replace('/api/releases/', '').replace('/archive', '')
            self.handle_toggle_release_archive(release_id)
        else:
            self.send_error(404, f"Unknown PATCH endpoint: {path}")

    def do_DELETE(self):
        """Handle DELETE requests"""
        # XACA-0395: central auth gate — must stay the first statement.
        if not self._auth_gate():
            return

        parsed = urlparse(self.path)
        path = parsed.path

        # Strip known path prefixes for Tailscale funnel compatibility
        for prefix in self.PATH_PREFIXES:
            if path.startswith(prefix + '/'):
                path = path[len(prefix):] or '/'
                break

        # Release API endpoints
        if path.startswith('/api/releases/') and '/items/' in path:
            # DELETE /api/releases/<id>/items/<itemId>
            parts = path.replace('/api/releases/', '').split('/items/')
            if len(parts) == 2:
                release_id, item_id = parts
                self.handle_remove_item_from_release(release_id, item_id)
            else:
                self.send_error(400, "Invalid path format")
        elif path.startswith('/api/releases/') and '/crs/' in path:
            # DELETE /api/releases/<id>/crs/<crId> — unlink a CR (XACA-0657)
            parts = path[len('/api/releases/'):].split('/crs/', 1)
            if len(parts) == 2:
                release_id, cr_id = parts
                self.handle_unlink_cr_from_release(release_id, cr_id)
            else:
                self.send_error(400, "Invalid path format for CR unlink")
        elif path.startswith('/api/releases/'):
            release_id = path.replace('/api/releases/', '')
            self.handle_archive_release(release_id)
        # Epic API endpoints
        elif path.startswith('/api/epics/') and '/items/' in path:
            # DELETE /api/epics/<id>/items/<itemId>
            parts = path.replace('/api/epics/', '').split('/items/')
            if len(parts) == 2:
                epic_id, item_id = parts
                self.handle_remove_item_from_epic(epic_id, item_id)
            else:
                self.send_error(400, "Invalid path format")
        elif path.startswith('/api/epics/'):
            epic_id = path.replace('/api/epics/', '')
            self.handle_delete_epic(epic_id)
        # Todo API endpoints
        elif path == '/api/todos':
            self.handle_delete_todo()
        # Weekly anchor API endpoints (XACA-0253-003)
        elif path == '/api/weekly-anchor':
            self.handle_delete_weekly_anchor()
        # Alert ingestion endpoints (XACA-0334-002)
        elif path.startswith('/api/alerts/'):
            alert_id = path[len('/api/alerts/'):]
            self.handle_delete_alert(alert_id)
        else:
            self.send_error(404, f"Unknown DELETE endpoint: {path}")

    def _find_item_index(self, data, item_id):
        """Find backlog item index by ID. Returns -1 if not found."""
        if 'backlog' not in data:
            return -1
        for i, item in enumerate(data['backlog']):
            if item.get('id') == item_id:
                return i
        return -1

    def _resolve_selector(self, data, selector):
        """Resolve selector (ID or index) to array index. Returns -1 if not found."""
        # Check if it's a JIRA-style ID (X followed by 3 letters, dash, digits)
        if re.match(r'^X[A-Z]{3}-\d+$', str(selector)):
            return self._find_item_index(data, selector)
        # Otherwise treat as numeric index
        try:
            index = int(selector)
            if 'backlog' in data and 0 <= index < len(data['backlog']):
                return index
            return -1
        except (ValueError, TypeError):
            return -1

    def handle_toggle_collapsed(self):
        """Toggle collapsed state for a backlog item"""
        try:
            content_length = int(self.headers['Content-Length'])
            post_data = json.loads(self.rfile.read(content_length))

            team = post_data.get('team')
            item_id = post_data.get('id') or post_data.get('index')  # Support both id and index
            collapsed = post_data.get('collapsed')

            print(f"[LCARS] toggle-collapsed: team={team}, id={item_id}, collapsed={collapsed}")

            if team is None or item_id is None or collapsed is None:
                print(f"[LCARS] ERROR: Missing fields - team={team}, id={item_id}, collapsed={collapsed}")
                self.send_error(400, "Missing required fields: team, id (or index), collapsed")
                return

            board_file = get_board_file(team)
            if not board_file.exists():
                self.send_error(404, f"Board not found: {team}")
                return

            # Read, update, write with file locking
            lock_file = board_file.with_suffix('.json.lock')
            import fcntl

            with open(lock_file, 'w') as lock:
                fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
                try:
                    with open(board_file, 'r') as f:
                        data = json.load(f)

                    # Resolve selector to index
                    index = self._resolve_selector(data, item_id)
                    print(f"[LCARS] Resolved {item_id} to index {index}")

                    if index >= 0:
                        old_value = data['backlog'][index].get('collapsed')
                        data['backlog'][index]['collapsed'] = collapsed
                        data['lastUpdated'] = self._get_timestamp()

                        self._atomic_write_json(board_file, data)

                        print(f"[LCARS] Updated collapsed: {old_value} -> {collapsed} for {item_id}")

                        actual_item_id = data['backlog'][index].get('id', str(item_id))
                        if old_value != collapsed:
                            log_activity("collapsed_toggled", actual_item_id, "item",
                                         field="collapsed",
                                         old_value=str(old_value),
                                         new_value=str(collapsed))

                        self.send_response(200)
                        self.send_header('Content-Type', 'application/json')
                        self._send_cors_headers()
                        self.end_headers()
                        self.wfile.write(json.dumps({"success": True}).encode())
                    else:
                        print(f"[LCARS] ERROR: Item not found: {item_id}")
                        self.send_error(400, f"Item not found: {item_id}")
                finally:
                    fcntl.flock(lock.fileno(), fcntl.LOCK_UN)

        except Exception as e:
            self.send_error(500, f"Error updating collapsed state: {e}")

    def handle_update_item(self):
        """Update arbitrary fields on a backlog item"""
        try:
            content_length = int(self.headers['Content-Length'])
            post_data = json.loads(self.rfile.read(content_length))

            team = post_data.get('team')
            item_id = post_data.get('id') or post_data.get('index')  # Support both id and index
            updates = post_data.get('updates', {})

            if team is None or item_id is None:
                self.send_error(400, "Missing required fields: team, id (or index)")
                return

            board_file = get_board_file(team)
            if not board_file.exists():
                self.send_error(404, f"Board not found: {team}")
                return

            # Read, update, write with file locking
            lock_file = board_file.with_suffix('.json.lock')
            import fcntl

            with open(lock_file, 'w') as lock:
                fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
                try:
                    with open(board_file, 'r') as f:
                        data = json.load(f)

                    # Resolve selector to index
                    index = self._resolve_selector(data, item_id)

                    if index >= 0:
                        item = data['backlog'][index]
                        actual_item_id = item.get('id', item_id)

                        # Block completion if subitems are incomplete
                        if updates.get('status') == 'completed':
                            subitems = item.get('subitems', [])
                            incomplete = [s for s in subitems if s.get('status') not in ('completed', 'cancelled')]
                            if incomplete:
                                self.send_response(400)
                                self.send_header('Content-Type', 'application/json')
                                self._send_cors_headers()
                                self.end_headers()
                                self.wfile.write(json.dumps({
                                    "error": "Cannot complete item with incomplete subitems",
                                    "incompleteSubitems": [{"id": s.get("id"), "title": s.get("title"), "status": s.get("status")} for s in incomplete]
                                }).encode())
                                return

                        # Track old release assignment BEFORE applying updates
                        old_release_assignment = item.get('releaseAssignment')
                        old_release_id = old_release_assignment.get('releaseId') if old_release_assignment else None

                        # Snapshot old field values BEFORE applying updates (for activity logging)
                        old_values = {key: item.get(key) for key in updates}
                        old_tags = list(item.get('tags', []))

                        # Apply updates
                        for key, value in updates.items():
                            data['backlog'][index][key] = value

                        # Handle field clearing (delete fields from item)
                        clear_fields = post_data.get('clearFields', [])
                        for field in clear_fields:
                            if field in data['backlog'][index]:
                                del data['backlog'][index][field]

                        data['lastUpdated'] = self._get_timestamp()

                        self._atomic_write_json(board_file, data)

                        # Log activity for each changed field
                        for key, new_val in updates.items():
                            old_val = old_values.get(key)
                            if old_val == new_val:
                                continue
                            if key == 'status':
                                log_activity("status_change", actual_item_id, "item",
                                             field="status",
                                             old_value=str(old_val) if old_val is not None else None,
                                             new_value=str(new_val) if new_val is not None else None)
                            elif key == 'title':
                                log_activity("field_update", actual_item_id, "item",
                                             field="title",
                                             old_value=str(old_val) if old_val is not None else None,
                                             new_value=str(new_val) if new_val is not None else None)
                            elif key == 'priority':
                                log_activity("field_update", actual_item_id, "item",
                                             field="priority",
                                             old_value=str(old_val) if old_val is not None else None,
                                             new_value=str(new_val) if new_val is not None else None)
                            elif key == 'description':
                                old_str = str(old_val)[:100] if old_val is not None else None
                                new_str = str(new_val)[:100] if new_val is not None else None
                                log_activity("field_update", actual_item_id, "item",
                                             field="description",
                                             old_value=old_str,
                                             new_value=new_str)
                            elif key == 'tags':
                                new_tags = new_val if isinstance(new_val, list) else []
                                for tag in new_tags:
                                    if tag not in old_tags:
                                        log_activity("tag_added", actual_item_id, "item",
                                                     field="tags",
                                                     new_value=str(tag))
                                for tag in old_tags:
                                    if tag not in new_tags:
                                        log_activity("tag_removed", actual_item_id, "item",
                                                     field="tags",
                                                     old_value=str(tag))
                            else:
                                log_activity("field_update", actual_item_id, "item",
                                             field=key,
                                             old_value=str(old_val) if old_val is not None else None,
                                             new_value=str(new_val) if new_val is not None else None)

                        # Check new release assignment after updates
                        new_release_assignment = data['backlog'][index].get('releaseAssignment')
                        new_release_id = new_release_assignment.get('releaseId') if new_release_assignment else None

                        # If release assignment changed or was cleared, remove from old manifest
                        if old_release_id and old_release_id != new_release_id:
                            self._remove_item_from_release_manifest(old_release_id, actual_item_id)

                        # Sync to new manifest if assigned to a release
                        if new_release_id:
                            self._sync_item_to_release_manifest(
                                new_release_id,
                                actual_item_id,
                                data['backlog'][index]
                            )

                        self.send_response(200)
                        self.send_header('Content-Type', 'application/json')
                        self._send_cors_headers()
                        self.end_headers()
                        self.wfile.write(json.dumps({"success": True}).encode())
                    else:
                        self.send_error(400, f"Item not found: {item_id}")
                finally:
                    fcntl.flock(lock.fileno(), fcntl.LOCK_UN)

        except Exception as e:
            self.send_error(500, f"Error updating item: {e}")

    def handle_update_subitem(self):
        """Update arbitrary fields on a subitem"""
        try:
            content_length = int(self.headers['Content-Length'])
            post_data = json.loads(self.rfile.read(content_length))

            team = post_data.get('team')
            parent_index = post_data.get('parentIndex')
            sub_index = post_data.get('subIndex')
            updates = post_data.get('updates', {})

            if team is None or parent_index is None or sub_index is None:
                self.send_error(400, "Missing required fields: team, parentIndex, subIndex")
                return

            board_file = get_board_file(team)
            if not board_file.exists():
                self.send_error(404, f"Board not found: {team}")
                return

            # Read, update, write with file locking
            lock_file = board_file.with_suffix('.json.lock')
            import fcntl

            with open(lock_file, 'w') as lock:
                fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
                try:
                    with open(board_file, 'r') as f:
                        data = json.load(f)

                    # Validate indices
                    if 'backlog' not in data or parent_index >= len(data['backlog']):
                        self.send_error(400, f"Parent item not found: {parent_index}")
                        return

                    parent_item = data['backlog'][parent_index]
                    if 'subitems' not in parent_item or sub_index >= len(parent_item['subitems']):
                        self.send_error(400, f"Subitem not found: {parent_index}.{sub_index}")
                        return

                    subitem = parent_item['subitems'][sub_index]
                    actual_subitem_id = subitem.get('id', f"{parent_index}.{sub_index}")

                    # Snapshot old field values BEFORE applying updates (for activity logging)
                    old_subitem_values = {key: subitem.get(key) for key in updates}

                    # Apply updates to subitem
                    for key, value in updates.items():
                        data['backlog'][parent_index]['subitems'][sub_index][key] = value

                    # Handle field clearing (delete fields from subitem)
                    clear_fields = post_data.get('clearFields', [])
                    for field in clear_fields:
                        if field in data['backlog'][parent_index]['subitems'][sub_index]:
                            del data['backlog'][parent_index]['subitems'][sub_index][field]

                    # Update timestamps
                    data['backlog'][parent_index]['updatedAt'] = self._get_timestamp()
                    data['lastUpdated'] = self._get_timestamp()

                    self._atomic_write_json(board_file, data)

                    # Log activity for each changed subitem field
                    for key, new_val in updates.items():
                        old_val = old_subitem_values.get(key)
                        if old_val == new_val:
                            continue
                        if key == 'status':
                            log_activity("subitem_status_change", actual_subitem_id, "subitem",
                                         field="status",
                                         old_value=str(old_val) if old_val is not None else None,
                                         new_value=str(new_val) if new_val is not None else None)
                        elif key == 'title':
                            log_activity("field_update", actual_subitem_id, "subitem",
                                         field="title",
                                         old_value=str(old_val) if old_val is not None else None,
                                         new_value=str(new_val) if new_val is not None else None)
                        elif key == 'description':
                            old_str = str(old_val)[:100] if old_val is not None else None
                            new_str = str(new_val)[:100] if new_val is not None else None
                            log_activity("field_update", actual_subitem_id, "subitem",
                                         field="description",
                                         old_value=old_str,
                                         new_value=new_str)
                        else:
                            log_activity("field_update", actual_subitem_id, "subitem",
                                         field=key,
                                         old_value=str(old_val) if old_val is not None else None,
                                         new_value=str(new_val) if new_val is not None else None)

                    # Sync parent item to release manifest if it has a release assignment
                    parent_release = parent_item.get('releaseAssignment')
                    if parent_release and parent_release.get('releaseId'):
                        self._sync_item_to_release_manifest(
                            parent_release['releaseId'],
                            parent_item.get('id'),
                            data['backlog'][parent_index]
                        )

                    self.send_response(200)
                    self.send_header('Content-Type', 'application/json')
                    self._send_cors_headers()
                    self.end_headers()
                    self.wfile.write(json.dumps({"success": True}).encode())
                finally:
                    fcntl.flock(lock.fileno(), fcntl.LOCK_UN)

        except Exception as e:
            self.send_error(500, f"Error updating subitem: {e}")

    # ============================================================
    # Integration API Handlers (Multi-Platform Support)
    # ============================================================

    def handle_integration_search(self):
        """Search for tickets across configured integrations"""
        if not INTEGRATIONS_AVAILABLE:
            self._send_json_response({"error": "Integration module not available"})
            return

        try:
            content_length = int(self.headers['Content-Length'])
            post_data = json.loads(self.rfile.read(content_length))

            query = post_data.get('query', '').strip()
            integration_id = post_data.get('integrationId')
            team = post_data.get('team', LCARS_TEAM)
            max_results = post_data.get('maxResults', 10)

            if not query:
                self._send_json_response({"results": {}})
                return

            manager = get_manager()
            results = manager.search(
                query=query,
                integration_id=integration_id,
                team=team,
                max_results=max_results
            )

            # Convert to JSON-serializable format
            response = {"results": {}}
            for int_id, search_result in results.items():
                response["results"][int_id] = {
                    "tickets": [
                        {
                            "ticketId": t.ticket_id,
                            "summary": t.summary,
                            "status": t.status,
                            "type": t.ticket_type,
                            "url": t.url
                        }
                        for t in search_result.tickets
                    ],
                    "error": search_result.error,
                    "totalCount": search_result.total_count
                }

            self._send_json_response(response)

        except Exception as e:
            self.send_error(500, f"Error in integration search: {e}")

    def handle_integration_verify(self):
        """Verify a ticket exists in configured integrations"""
        if not INTEGRATIONS_AVAILABLE:
            self._send_json_response({"error": "Integration module not available"})
            return

        try:
            content_length = int(self.headers['Content-Length'])
            post_data = json.loads(self.rfile.read(content_length))

            ticket_id = post_data.get('ticketId', '').strip()
            integration_id = post_data.get('integrationId')

            if not ticket_id:
                self._send_json_response({
                    "valid": False,
                    "error": "No ticket ID provided"
                })
                return

            manager = get_manager()
            results = manager.verify(
                ticket_id=ticket_id,
                integration_id=integration_id
            )

            # Convert to JSON-serializable format
            response = {"results": {}}
            for int_id, verify_result in results.items():
                response["results"][int_id] = {
                    "valid": verify_result.valid,
                    "ticketId": verify_result.ticket_id,
                    "exists": verify_result.exists,
                    "summary": verify_result.summary,
                    "status": verify_result.status,
                    "type": verify_result.ticket_type,
                    "url": verify_result.url,
                    "warning": verify_result.warning,
                    "error": verify_result.error
                }

            # For single integration, also return flat response
            if integration_id and integration_id in response["results"]:
                response.update(response["results"][integration_id])

            self._send_json_response(response)

        except Exception as e:
            self.send_error(500, f"Error in integration verify: {e}")

    def handle_integration_test(self):
        """Test connection to a specific integration"""
        if not INTEGRATIONS_AVAILABLE:
            self._send_json_response({
                "success": False,
                "message": "Integration module not available"
            })
            return

        try:
            content_length = int(self.headers['Content-Length'])
            post_data = json.loads(self.rfile.read(content_length))

            integration_id = post_data.get('integrationId')

            if not integration_id:
                self._send_json_response({
                    "success": False,
                    "message": "No integration ID provided"
                })
                return

            manager = get_manager()
            result = manager.test_connection(integration_id)

            self._send_json_response({
                "success": result.success,
                "message": result.message,
                "details": result.details
            })

        except Exception as e:
            self.send_error(500, f"Error in integration test: {e}")

    def handle_integration_save(self):
        """Save (add or update) an integration to config file"""
        try:
            content_length = int(self.headers['Content-Length'])
            post_data = json.loads(self.rfile.read(content_length))

            integration = post_data.get('integration')
            is_new = post_data.get('isNew', False)

            if not integration or not integration.get('id'):
                self._send_json_response({
                    "success": False,
                    "error": "Invalid integration data"
                })
                return

            # Load current config (team-specific)
            config_path = INTEGRATIONS_FILE
            TEAM_CONFIG_DIR.mkdir(parents=True, exist_ok=True)

            # XACA-0890-003: hold the path lock across the whole read-modify-
            # write. INTEGRATIONS_FILE has no other protection (unlike
            # board_file's fcntl convention) — locking only the write below
            # would leave the read+merge above racing against a concurrent
            # save, which is exactly the lost-update window that made this
            # site unsafe once the server goes multi-threaded (XACA-0890-004).
            with _get_path_lock(config_path):
                if config_path.exists():
                    with open(config_path, 'r') as f:
                        config = json.load(f)
                else:
                    config = {"integrations": []}

                integrations = config.get('integrations', [])

                # Find existing integration
                existing_idx = None
                for i, integ in enumerate(integrations):
                    if integ.get('id') == integration['id']:
                        existing_idx = i
                        break

                if is_new and existing_idx is not None:
                    self._send_json_response({
                        "success": False,
                        "error": f"Integration with ID '{integration['id']}' already exists"
                    })
                    return

                # Build the integration config object
                new_config = {
                    'id': integration['id'],
                    'type': integration.get('type', 'custom'),
                    'name': integration.get('name', integration['id']),
                    'enabled': integration.get('enabled', True),
                    'baseUrl': integration.get('baseUrl', ''),
                    'browseUrl': integration.get('browseUrl', ''),
                }

                # Optional fields
                if integration.get('ticketPattern'):
                    new_config['ticketPattern'] = integration['ticketPattern']
                if integration.get('defaultProjects'):
                    new_config['defaultProjects'] = integration['defaultProjects']
                if integration.get('auth'):
                    new_config['auth'] = integration['auth']
                if integration.get('icon'):
                    new_config['icon'] = integration['icon']

                # Add API version for JIRA
                if integration.get('type') == 'jira':
                    new_config['apiVersion'] = '3'

                # Update or add
                if existing_idx is not None:
                    integrations[existing_idx] = new_config
                else:
                    integrations.append(new_config)

                config['integrations'] = integrations

                # Write back atomically
                self._atomic_write_json(config_path, config)

            # Reload the manager (must use reload() not load() to clear cache)
            if INTEGRATIONS_AVAILABLE:
                manager = get_manager()
                manager.reload()

            self._send_json_response({
                "success": True,
                "message": "Integration saved"
            })

        except Exception as e:
            self._send_json_response({
                "success": False,
                "error": str(e)
            })

    def handle_integration_delete(self):
        """Delete an integration from config file"""
        try:
            content_length = int(self.headers['Content-Length'])
            post_data = json.loads(self.rfile.read(content_length))

            integration_id = post_data.get('integrationId')

            if not integration_id:
                self._send_json_response({
                    "success": False,
                    "error": "No integration ID provided"
                })
                return

            # Load current config (team-specific)
            config_path = INTEGRATIONS_FILE
            if not config_path.exists():
                self._send_json_response({
                    "success": False,
                    "error": "No integrations configured for this team"
                })
                return

            # XACA-0890-003: same path lock as handle_integration_save — see
            # that method's comment for why the whole read-modify-write (not
            # just the write) must be inside it.
            with _get_path_lock(config_path):
                with open(config_path, 'r') as f:
                    config = json.load(f)

                integrations = config.get('integrations', [])
                original_count = len(integrations)

                # Remove the integration
                integrations = [i for i in integrations if i.get('id') != integration_id]

                if len(integrations) == original_count:
                    self._send_json_response({
                        "success": False,
                        "error": f"Integration '{integration_id}' not found"
                    })
                    return

                config['integrations'] = integrations

                # Write back atomically
                self._atomic_write_json(config_path, config)

            # Reload the manager (must use reload() not load() to clear cache)
            if INTEGRATIONS_AVAILABLE:
                manager = get_manager()
                manager.reload()

            self._send_json_response({
                "success": True,
                "message": "Integration deleted"
            })

        except Exception as e:
            self._send_json_response({
                "success": False,
                "error": str(e)
            })

    def handle_integration_boards(self):
        """Fetch boards from Monday.com integration for board selection UI"""
        if not INTEGRATIONS_AVAILABLE:
            self._send_json_response({
                "success": False,
                "error": "Integration module not available"
            })
            return

        try:
            content_length = int(self.headers['Content-Length'])
            post_data = json.loads(self.rfile.read(content_length))

            integration_id = post_data.get('integrationId')

            if not integration_id:
                self._send_json_response({
                    "success": False,
                    "error": "No integration ID provided"
                })
                return

            manager = get_manager()
            provider = manager.get_provider(integration_id)

            if not provider:
                self._send_json_response({
                    "success": False,
                    "error": f"Integration '{integration_id}' not found"
                })
                return

            # Check if this is a Monday.com provider with get_boards method
            if provider.provider_type != 'monday':
                self._send_json_response({
                    "success": False,
                    "error": "Board fetching is only supported for Monday.com integrations"
                })
                return

            if not hasattr(provider, 'get_boards'):
                self._send_json_response({
                    "success": False,
                    "error": "Provider does not support board fetching"
                })
                return

            if not provider.has_credentials():
                self._send_json_response({
                    "success": False,
                    "error": "Monday.com credentials not configured"
                })
                return

            # Fetch boards from Monday.com
            limit = post_data.get('limit', 50)
            boards = provider.get_boards(limit=limit)

            self._send_json_response({
                "success": True,
                "boards": boards
            })

        except Exception as e:
            self._send_json_response({
                "success": False,
                "error": str(e)
            })

    def handle_integration_create_item(self):
        """Create a new item in an external integration (Monday.com, JIRA, etc.)"""
        if not INTEGRATIONS_AVAILABLE:
            self._send_json_response({
                "success": False,
                "error": "Integration module not available"
            })
            return

        try:
            content_length = int(self.headers['Content-Length'])
            post_data = json.loads(self.rfile.read(content_length))

            # Required fields
            integration_id = post_data.get('integrationId')
            board_id = post_data.get('boardId')
            title = post_data.get('title')

            # Optional fields
            description = post_data.get('description')
            metadata = post_data.get('metadata', {})

            # Validation
            if not integration_id:
                self._send_json_response({
                    "success": False,
                    "error": "Missing required field: integrationId"
                })
                return

            if not board_id:
                self._send_json_response({
                    "success": False,
                    "error": "Missing required field: boardId"
                })
                return

            if not title or not title.strip():
                self._send_json_response({
                    "success": False,
                    "error": "Missing required field: title"
                })
                return

            # Get the integration provider
            manager = get_manager()
            provider = manager.get_provider(integration_id)

            if not provider:
                self._send_json_response({
                    "success": False,
                    "error": f"Integration '{integration_id}' not found"
                })
                return

            if not provider.has_credentials():
                self._send_json_response({
                    "success": False,
                    "error": f"Integration '{integration_id}' credentials not configured"
                })
                return

            # Create the item using the provider
            result = provider.create_item(
                board_id=board_id,
                title=title,
                description=description,
                metadata=metadata
            )

            # Convert result to JSON response
            response = {
                "success": result.success,
                "ticketId": result.ticket_id,
                "url": result.url,
                "message": result.message,
                "error": result.error
            }

            self._send_json_response(response)

        except Exception as e:
            self._send_json_response({
                "success": False,
                "error": f"Unexpected error: {str(e)}"
            })

